cd claude-code-game-master/build/ai-table-gm-console-concept/sonnet/assets/store; python3 - <<'EOF'
import struct
for f in ['hero-guardian.webp','hero-fury.webp','token-tinnik-big.webp','portrait-guardian.webp','backdrop-ford.webp']:
    d=open(f,'rb').read(40)
    # VP8/VP8L/VP8X dims
    if d[12:16]==b'VP8X':
        w=1+int.from_bytes(d[24:27],'little'); h=1+int.from_bytes(d[27:30],'little')
    elif d[12:16]==b'VP8 ':
        w,h=struct.unpack('<HH',d[26:30]); w&=0x3fff; h&=0x3fff
    else:
        b=int.from_bytes(d[21:25],'little'); w=(b&0x3fff)+1; h=((b>>14)&0x3fff)+1
    print(f,w,h)
EOF
